#define DT_DRV_COMPAT zephyr_espi_emul

#include <zephyr/drivers/espi.h>
#include <zephyr/drivers/espi_emul.h>
#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>
#include <zephyr/spinlock.h>

LOG_MODULE_REGISTER(espi_emul, CONFIG_ESPI_EMUL_LOG_LEVEL);

struct espi_emul_cfg {
	struct espi_emul_api_callback *api_callback_list;
	const struct device *host_dev;
};

struct espi_emul_data {
	struct k_spinlock lock;
	struct espi_callback callback_list;
};

static int espi_emul_init(const struct device *dev)
{
	const struct espi_emul_cfg *cfg = dev->config;
	struct espi_emul_data *data = dev->data;

	LOG_DBG("eSPI emulator init");

	k_spinlock_init(&data->lock);

	if (cfg->host_dev) {
		if (!device_is_ready(cfg->host_dev)) {
			LOG_ERR("Host device %s is not ready", cfg->host_dev->name);
			return -ENODEV;
		}
	}

	return 0;
}

static int espi_emul_read_lpc_io(const struct device *dev, uint32_t addr, uint32_t *val)
{
	struct espi_emul_data *data = dev->data;
	k_spinlock_key_t key = k_spin_lock(&data->lock);

	int ret = espi_emul_call_callbacks(dev, &data->callback_list,
					   ESPI_BUS_EVENT_VWIRE_RECEIVED, ESPI_VWIRE_LPC_IO_READ,
					   addr, val);

	k_spin_unlock(&key);

	return ret;
}

static int espi_emul_write_lpc_io(const struct device *dev, uint32_t addr, uint32_t val)
{
	struct espi_emul_data *data = dev->data;
	k_spinlock_key_t key = k_spin_lock(&data->lock);

	int ret = espi_emul_call_callbacks(dev, &data->callback_list,
					   ESPI_BUS_EVENT_VWIRE_RECEIVED, ESPI_VWIRE_LPC_IO_WRITE,
					   addr, &val);

	k_spin_unlock(&key);

	return ret;
}

static int espi_emul_read_lpc_mem(const struct device *dev, uint32_t addr, uint32_t *val)
{
	struct espi_emul_data *data = dev->data;
	k_spinlock_key_t key = k_spin_lock(&data->lock);

	int ret = espi_emul_call_callbacks(dev, &data->callback_list,
					   ESPI_BUS_EVENT_VWIRE_RECEIVED, ESPI_VWIRE_LPC_MEM_READ,
					   addr, val);

	k_spin_unlock(&key);

	return ret;
}

static int espi_emul_write_lpc_mem(const struct device *dev, uint32_t addr, uint32_t val)
{
	struct espi_emul_data *data = dev->data;
	k_spinlock_key_t key = k_spin_lock(&data->lock);

	int ret = espi_emul_call_callbacks(dev, &data->callback_list,
					   ESPI_BUS_EVENT_VWIRE_RECEIVED, ESPI_VWIRE_LPC_MEM_WRITE,
					   addr, &val);

	k_spin_unlock(&key);

	return ret;
}

static int espi_emul_read_lpc_vwire(const struct device *dev, enum espi_vwire_signal signal,
				    uint8_t *val)
{
	struct espi_emul_data *data = dev->data;
	k_spinlock_key_t key = k_spin_lock(&data->lock);

	int ret = espi_emul_call_callbacks(dev, &data->callback_list,
					   ESPI_BUS_EVENT_VWIRE_RECEIVED, signal, 0, (uint32_t *)val);

	k_spin_unlock(&key);

	return ret;
}

static int espi_emul_write_lpc_vwire(const struct device *dev, enum espi_vwire_signal signal,
				     uint8_t val)
{
	struct espi_emul_data *data = dev->data;
	k_spinlock_key_t key = k_spin_lock(&data->lock);

	int ret = espi_emul_call_callbacks(dev, &data->callback_list,
					   ESPI_BUS_EVENT_VWIRE_RECEIVED, signal, 0, (uint32_t *)&val);

	k_spin_unlock(&key);

	return ret;
}

static int espi_emul_send_vwire(const struct device *dev, enum espi_vwire_signal signal,
				uint8_t val)
{
	struct espi_emul_data *data = dev->data;
	k_spinlock_key_t key = k_spin_lock(&data->lock);

	int ret = espi_emul_call_callbacks(dev, &data->callback_list,
					   ESPI_BUS_EVENT_VWIRE_SENT, signal, 0, (uint32_t *)&val);

	k_spin_unlock(&key);

	return ret;
}

static int espi_emul_receive_vwire(const struct device *dev, enum espi_vwire_signal signal,
				   uint8_t *val)
{
	struct espi_emul_data *data = dev->data;
	k_spinlock_key_t key = k_spin_lock(&data->lock);

	int ret = espi_emul_call_callbacks(dev, &data->callback_list,
					   ESPI_BUS_EVENT_VWIRE_RECEIVED, signal, 0, (uint32_t *)val);

	k_spin_unlock(&key);

	return ret;
}

static int espi_emul_read_flash(const struct device *dev, uint32_t addr, void *buf, size_t len)
{
	struct espi_emul_data *data = dev->data;
	k_spinlock_key_t key = k_spin_lock(&data->lock);

	int ret = espi_emul_call_callbacks(dev, &data->callback_list,
					   ESPI_BUS_EVENT_FLASH_RECEIVED, ESPI_VWIRE_NONE, addr, buf);

	k_spin_unlock(&key);

	return ret;
}

static int espi_emul_write_flash(const struct device *dev, uint32_t addr, const void *buf,
				 size_t len)
{
	struct espi_emul_data *data = dev->data;
	k_spinlock_key_t key = k_spin_lock(&data->lock);

	int ret = espi_emul_call_callbacks(dev, &data->callback_list,
					   ESPI_BUS_EVENT_FLASH_SENT, ESPI_VWIRE_NONE, addr, (void *)buf);

	k_spin_unlock(&key);

	return ret;
}

static int espi_emul_flash_erase(const struct device *dev, uint32_t addr, size_t size)
{
	struct espi_emul_data *data = dev->data;
	k_spinlock_key_t key = k_spin_lock(&data->lock);

	int ret = espi_emul_call_callbacks(dev, &data->callback_list,
					   ESPI_BUS_EVENT_FLASH_ERASE, ESPI_VWIRE_NONE, addr, (void *)size);

	k_spin_unlock(&key);

	return ret;
}

static int espi_emul_flash_write_protection(const struct device *dev, bool enable)
{
	struct espi_emul_data *data = dev->data;
	k_spinlock_key_t key = k_spin_lock(&data->lock);

	int ret = espi_emul_call_callbacks(dev, &data->callback_list,
					   ESPI_BUS_EVENT_FLASH_WP, ESPI_VWIRE_NONE, 0, (void *)enable);

	k_spin_unlock(&key);

	return ret;
}

static int espi_emul_read_oob(const struct device *dev, uint32_t addr, void *buf, size_t len)
{
	struct espi_emul_data *data = dev->data;
	k_spinlock_key_t key = k_spin_lock(&data->lock);

	int ret = espi_emul_call_callbacks(dev, &data->callback_list,
					   ESPI_BUS_EVENT_OOB_RECEIVED, ESPI_VWIRE_NONE, addr, buf);

	k_spin_unlock(&key);

	return ret;
}

static int espi_emul_write_oob(const struct device *dev, uint32_t addr, const void *buf,
			       size_t len)
{
	struct espi_emul_data *data = dev->data;
	k_spinlock_key_t key = k_spin_lock(&data->lock);

	int ret = espi_emul_call_callbacks(dev, &data->callback_list,
					   ESPI_BUS_EVENT_OOB_SENT, ESPI_VWIRE_NONE, addr, (void *)buf);

	k_spin_unlock(&key);

	return ret;
}

static int espi_emul_manage_callback(const struct device *dev, struct espi_callback *callback,
				     bool set)
{
	struct espi_emul_data *data = dev->data;
	k_spinlock_key_t key = k_spin_lock(&data->lock);

	if (set) {
		slist_append(&data->callback_list.node, &callback->node);
	} else {
		slist_remove(&data->callback_list.node, &callback->node);
	}

	k_spin_unlock(&key);

	return 0;
}

static const struct espi_driver_api espi_emul_api = {
	.read_lpc_io = espi_emul_read_lpc_io,
	.write_lpc_io = espi_emul_write_lpc_io,
	.read_lpc_mem = espi_emul_read_lpc_mem,
	.write_lpc_mem = espi_emul_write_lpc_mem,
	.read_lpc_vwire = espi_emul_read_lpc_vwire,
	.write_lpc_vwire = espi_emul_write_lpc_vwire,
	.send_vwire = espi_emul_send_vwire,
	.receive_vwire = espi_emul_receive_vwire,
	.read_flash = espi_emul_read_flash,
	.write_flash = espi_emul_write_flash,
	.flash_erase = espi_emul_flash_erase,
	.flash_write_protection = espi_emul_flash_write_protection,
	.read_oob = espi_emul_read_oob,
	.write_oob = espi_emul_write_oob,
	.manage_callback = espi_emul_manage_callback,
};

#define ESPI_EMUL_INIT(n)                                                                          \
	static const struct espi_emul_cfg espi_emul_cfg_##n = {                                        \
		.api_callback_list = NULL,                                                                 \
		.host_dev = DEVICE_DT_GET_OR_NULL(DT_INST_PHANDLE_BY_IDX(n, host, 0)),                     \
	};                                                                                             \
                                                                                                   \
	static struct espi_emul_data espi_emul_data_##n = {                                            \
		.lock = Z_SPINLOCK_INITIALIZER(espi_emul_data_##n.lock),                                   \
	};                                                                                             \
                                                                                                   \
	IF_ENABLED(DT_INST_NODE_HAS_STATUS(n, okay), (                                                 \
	DEVICE_DT_INST_DEFINE(n, espi_emul_init, NULL, &espi_emul_data_##n, &espi_emul_cfg_##n,        \
				  POST_KERNEL, CONFIG_ESPI_EMUL_INIT_PRIORITY, &espi_emul_api);        \
	))

DT_INST_FOREACH_STATUS_OKAY(ESPI_EMUL_INIT)
